from django.db import migrations, models


# Rank thresholds before the 2026-11-19 level system (index = level - 1).
# Frozen here on purpose: this migration must keep computing the *old*
# rank even after ranks.RANK_LEVELS changes again.
OLD_RANK_MINS = [0, 50, 100, 200, 300, 450, 650, 900, 1200, 2000]
NEW_RANK_MINS = [0, 150, 350, 600, 900, 1300, 1800, 2400, 3100, 4000]


def _level(score, mins):
    level = 1
    for i, minimum in enumerate(mins, start=1):
        if score >= minimum:
            level = i
    return level


def init_max_level(apps, schema_editor):
    """Existing users keep the rank they already had: the higher of the old-
    and new-threshold level for their current points (the old thresholds are
    lower, so in practice the old rank). Nobody goes down."""
    Profile = apps.get_model('thank_japan_app', 'Profile')
    to_update = []
    for profile in Profile.objects.only('id', 'total_score', 'max_level').iterator():
        score = profile.total_score or 0
        level = max(_level(score, OLD_RANK_MINS), _level(score, NEW_RANK_MINS))
        if level != profile.max_level:
            profile.max_level = level
            to_update.append(profile)
    Profile.objects.bulk_update(to_update, ['max_level'], batch_size=500)


